<?php
function dashboardView(): void {
    $u=need();$menu=menu(today());$available=count(array_filter($menu,fn($x)=>$x['available']));$low=rows('SELECT i.name,i.reorder_level,u.symbol,COALESCE(m.balance,0) balance FROM inventory_items i JOIN units u ON u.unit_id=i.unit_id LEFT JOIN (SELECT inventory_item_id,SUM(quantity_change) balance FROM stock_movements GROUP BY inventory_item_id) m ON m.inventory_item_id=i.inventory_item_id WHERE i.is_active=1 AND COALESCE(m.balance,0)<=i.reorder_level');
    $first=explode(' ',$u['full_name'])[0];heading('A FRESH DAY AT THE COUNTER','Kumusta, '.$first.'!','Here’s what’s happening in your carinderia today.',in_array($u['role_name'],['Owner','Cashier'])?'<a class="btn primary" href="?page=pos">'.icon('plus').' New sale</a>':'<a class="btn primary" href="?page=daily-menu">Prepare today’s menu →</a>');
    echo '<section class="welcome-banner"><div><span class="banner-label">GOOD FOOD. SMOOTHER DAYS.</span><h2>Your kitchen, in good hands.</h2><p>Keep the meals moving and the little details taken care of.</p><a href="?page=refills">Check active meals '.icon('arrow').'</a></div><div class="banner-art" aria-hidden="true"><span class="art-orbit"></span><span class="rice-bowl"><img class="food-icon" src="assets/food/rice.svg" alt=""></span><span class="spark s1">✦</span><span class="spark s2">✦</span><span class="art-note">Lutong bahay ♥</span></div></section>';
    $sql='SELECT COALESCE(SUM(total_amount),0) total,COUNT(*) count FROM sales s JOIN cash_sessions c ON c.cash_session_id=s.cash_session_id WHERE sold_at>=? AND sold_at<?';$args=[today(),date('Y-m-d',strtotime('+1 day'))];if($u['role_name']==='Cashier'){$sql.=' AND c.user_id=?';$args[]=$u['user_id'];}$sum=one($sql,$args);
    echo '<div class="metrics">';if($u['role_name']!=='Staff'){metric('Today’s sales',money($sum['total']),$u['role_name']==='Cashier'?'Your transactions only':'Completed cash transactions','cash');metric('Orders served',(string)$sum['count'],'Recorded today','bag');}else{metric('Prepared portions',(string)array_sum(array_column($menu,'prepared_qty')),'Today’s kitchen output','bowl');metric('Rice refills',(string)val("SELECT COUNT(*) FROM sale_item_components WHERE serving_type='refill' AND served_at>=?",[today()]),'Extra servings recorded today','leaf');}metric('On the menu',(string)$available,'Available dishes, drinks & combos','bowl');metric('Stock alerts',(string)count($low),'Ingredients at or below reorder level','box');echo '</div>';
    echo '<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>'.($u['role_name']==='Staff'?'Kitchen availability':'Sales at a glance').'</h2><p>'.($u['role_name']==='Staff'?'Prepared portions remaining today':'The last 7 days · Actual recorded sales').'</p></div>'.badge('LIVE DATA','green').'</div>';
    if($u['role_name']!=='Staff'){
        $a=[date('Y-m-d',strtotime('-6 days'))];$extra='';if($u['role_name']==='Cashier'){$extra=' AND c.user_id=?';$a[]=$u['user_id'];}$data=rows('SELECT DATE(s.sold_at) day,SUM(total_amount) total FROM sales s JOIN cash_sessions c ON c.cash_session_id=s.cash_session_id WHERE s.sold_at>=?'.$extra.' GROUP BY DATE(s.sold_at)',$a);$by=array_column($data,'total','day');$vals=[];for($i=6;$i>=0;$i--)$vals[]=[$d=date('Y-m-d',strtotime("-$i days")),(float)($by[$d]??0)];$max=max(1,...array_column($vals,1));
        echo '<div class="chart" role="img" aria-label="Sales bar chart for the last seven days">';foreach($vals as [$day,$v])echo '<div class="chart-col"><span class="chart-value">'.money($v).'</span><div class="bar-track"><div class="bar" style="height:'.max(1,round($v/$max*100)).'%"></div></div><span>'.h(date('D',strtotime($day))).'</span></div>';echo '</div>';
    }else{foreach(array_slice(array_filter($menu,fn($m)=>$m['item_type']!=='combo'),0,7)as $m)echo '<div class="stock-line"><span>'.foodEmoji($m['name']).' '.h($m['name']).'</span><b>'.$m['remaining'].' portions</b></div>';if(!$menu)emptyState('Add today’s dishes to begin.');}
    echo '</section><section class="panel"><div class="panel-head"><div><h2>A little heads-up</h2><p>Your daily attention list</p></div>'.icon('leaf').'</div>';if(!$low)echo '<div class="calm"><span>✓</span><h3>Stock looks healthy.</h3><p>No low-stock ingredients right now.</p></div>';foreach(array_slice($low,0,5)as $l)echo '<div class="alert-row"><div class="alert-icon">!</div><div><strong>'.h($l['name']).'</strong><small>'.h($l['balance'].' '.$l['symbol']).' left · reorder at '.h($l['reorder_level']).'</small></div></div>';if($u['role_name']!=='Cashier')echo '<a class="text-link" href="?page=inventory">View stock overview →</a>';echo '</section></div>';
    echo '<section class="panel"><div class="panel-head"><div><h2>Today’s favorites, ready to serve</h2><p>Your current daily menu</p></div>'.badge(count($menu).' listings').'</div><div class="mini-menu">';foreach(array_slice($menu,0,6)as $m)echo '<div class="mini-dish"><span>'.foodEmoji($m['name']).'</span><div><strong>'.h($m['name']).'</strong><small>'.h($m['remaining']).' available</small></div><b>'.money($m['selling_price']).'</b></div>';echo '</div>';if(!$menu)emptyState('Publish your daily menu to see it here.');echo '</section>';
}
function posView(): void {
    $menu=menu(today());$s=openSession();heading('QUICK COUNTER','What’s cooking?','Tap a dish, take the cash, and keep the queue moving.','<a class="btn ghost" href="?page=cash-session">'.icon('cash').' Cash drawer</a>');
    if(!$s)echo '<div class="notice warning">You need your own open cash session to complete sales. <a href="?page=cash-session">Open the drawer →</a></div>';
    echo '<div class="pos-layout" id="pos" data-user="'.h(need()['user_id']).'" data-menu="'.h(json_encode($menu)).'"><section><div class="pos-tools"><div class="search-field">'.icon('search').'<input id="dish-search" aria-label="Find a dish" placeholder="Search a dish or drink…"><kbd>/</kbd></div><button type="button" id="refresh-menu" class="btn ghost">Refresh menu</button></div><div class="category-tabs"><button type="button" class="tab active" data-category="all">All items</button>';foreach(array_unique(array_column($menu,'category'))as $cat)echo '<button type="button" class="tab" data-category="'.h($cat).'">'.h($cat).'</button>';echo '</div><div class="dish-grid">';
    foreach($menu as $m)echo '<button type="button" class="dish-card '.(!$m['available']?'sold-out':'').'" data-add="'.(int)$m['daily_menu_item_id'].'" data-name="'.h(mb_strtolower($m['name'])).'" data-cat="'.h($m['category']).'" '.(!$m['available']?'disabled':'').'><div class="dish-art art-'.h($m['item_type']).'"><span>'.foodEmoji($m['name']).'</span>'.($m['includes_unli_rice']?'<em>UNLI RICE</em>':'').'</div><div class="dish-info"><small>'.h($m['category']).'</small><h3>'.h($m['name']).'</h3><div><strong>'.money($m['selling_price']).'</strong><span class="portion">'.($m['available']?$m['remaining'].' left':'Unavailable').'</span></div></div></button>';
    echo '</div><p class="hint">Menu availability is checked again when you pay. Initial rice is included in unli meals; refills apply to dine-in only.</p></section><aside class="order-panel"><div class="panel-head"><div><h2>Current order</h2><p>Good food, coming right up.</p></div><button type="button" id="clear-cart" class="text-button">Clear</button></div>';
    formStart('checkout',['operation_token'=>token()],'checkout-form');echo '<div class="order-type"><label><input type="radio" name="order_type" value="dine_in" checked> Dine-in</label><label><input type="radio" name="order_type" value="takeout"> Takeout</label></div><div id="cart-lines"><div class="empty"><span class="cart-emoji"><img class="food-icon" src="assets/food/combo.svg" alt=""></span><h3>A fresh order starts here.</h3><p>Choose something delicious from the menu.</p></div></div><input type="hidden" name="cart" id="cart-json" value="[]"><div class="order-summary"><div><span>Items</span><span id="cart-count">0</span></div><div class="total"><span>Total</span><strong id="cart-total">₱0.00</strong></div></div>';
    field('Cash received','cash_tendered','number','','id="cash-received" min="0" step="0.01" required inputmode="decimal" placeholder="0.00"');echo '<div class="quick-cash"><button type="button" data-cash="exact">Exact</button><button type="button" data-cash="100">₱100</button><button type="button" data-cash="200">₱200</button><button type="button" data-cash="500">₱500</button></div><div class="change-line"><span>Change</span><strong id="cash-change">₱0.00</strong></div><button id="checkout-button" class="btn primary wide" '.(!$s?'disabled':'').'>Complete sale →</button><p class="hint center">Cash payment · Saved securely to your database</p></form></aside></div>';
}
function salesView(): void {
    heading('YOUR COUNTER RECORDS','Sales history','Every completed order, with its original prices and payment.');filterBar('Find a transaction or cashier…',true);$from=dateval($_GET['from']??today());$to=dateval($_GET['to']??today());$params=[$from,$to.' 23:59:59'];$where='s.sold_at BETWEEN ? AND ?';if(!owner()){$where.=' AND c.user_id=?';$params[]=need()['user_id'];}
    $r=rows('SELECT s.*,u.full_name FROM sales s JOIN cash_sessions c ON c.cash_session_id=s.cash_session_id JOIN users u ON u.user_id=c.user_id WHERE '.$where.' ORDER BY s.sale_id DESC',$params);$out=[];foreach($r as $s)if(matches($s['sale_number'].' '.$s['full_name']))$out[]=['<a class="text-link" href="?page=sale&id='.$s['sale_id'].'">'.h($s['sale_number']).'</a>',h($s['sold_at']),h($s['full_name']),badge(str_replace('_',' ',$s['order_type'])),money($s['total_amount']),badge('Paid','green')];echo '<section class="panel">';tableView(['Transaction','Date & time','Cashier','Order type','Total','Status'],$out);echo '</section>';
}
function saleView(): void {
    $id=integer($_GET['id']??0);$s=one('SELECT s.*,c.user_id,u.full_name,p.cash_tendered,p.change_given FROM sales s JOIN cash_sessions c ON c.cash_session_id=s.cash_session_id JOIN users u ON u.user_id=c.user_id JOIN payments p ON p.sale_id=s.sale_id WHERE s.sale_id=?',[$id]);if(!$s||(!owner()&&(int)$s['user_id']!==(int)need()['user_id']))throw new RuntimeException('Transaction not found or not accessible.');
    heading('COMPLETED TRANSACTION',$s['sale_number'],'A clear record of what was paid and served.','<button type="button" class="btn primary" data-print>Print slip</button>');echo '<section class="panel receipt-paper"><div class="receipt-brand">CarinderEase<span>Transaction slip</span></div><div class="receipt-meta"><span>'.h($s['sold_at']).'<br>'.h(str_replace('_',' ',$s['order_type'])).'</span><span>Cashier: '.h($s['full_name']).'<br>'.h($s['sale_number']).'</span></div>';
    $r=[];foreach(rows('SELECT * FROM sale_items WHERE sale_id=?',[$id])as $l)$r[]=[h($l['item_name_snapshot']).($l['unli_rice_granted']?' '.badge('Unli rice','green'):''),h($l['quantity']),money($l['unit_price']),money(dec(cents($l['unit_price'])*(int)$l['quantity']))];tableView(['Item','Qty','Price','Amount'],$r,'',false);echo '<div class="receipt-totals"><p>Total <strong>'.money($s['total_amount']).'</strong></p><p>Cash received <span>'.money($s['cash_tendered']).'</span></p><p>Change <strong>'.money($s['change_given']).'</strong></p></div><p class="center">Salamat po! Come back hungry. ♥</p><p class="hint center">Project transaction slip · Not an official tax invoice</p></section>';
}
function refillsView(): void {
    heading('A LITTLE MORE RICE','Active meals & refills','One extra serving at a time. No extra charge, every portion counted.');filterBar('Search transaction or meal…');
    $r=rows('SELECT i.*,s.sale_number,s.sold_at,(SELECT COALESCE(SUM(c.quantity),0) FROM sale_item_components c WHERE c.sale_item_id=i.sale_item_id AND c.serving_type=\'refill\') refills FROM sale_items i JOIN sales s ON s.sale_id=i.sale_id WHERE i.unli_rice_granted=1 AND s.sold_at>=? ORDER BY i.refill_closed_at IS NULL DESC,i.sale_item_id DESC',[today()]);
    echo '<div class="refill-grid">';foreach($r as $l)if(matches($l['sale_number'].' '.$l['item_name_snapshot'])){echo '<article class="panel refill-card"><div class="panel-head">'.badge($l['refill_closed_at']?'Visit closed':'At the table',$l['refill_closed_at']?'':'green').'<span class="muted">Meal #'.$l['sale_item_id'].'</span></div><span class="refill-emoji"><img class="food-icon" src="assets/food/rice.svg" alt=""></span><h2>'.h($l['item_name_snapshot']).'</h2><p class="muted">'.h($l['sale_number']).' · '.h(date('g:i A',strtotime($l['sold_at']))).'</p><div class="refill-count"><strong>'.$l['refills'].'</strong> extra rice servings</div>';if(!$l['refill_closed_at'])echo buttonForm('refill',['id'=>$l['sale_item_id'],'operation_token'=>token()],'+ Serve one rice','','primary wide').buttonForm('visit_close',['id'=>$l['sale_item_id']],'Close visit','Close this visit? Further refills will be blocked.','ghost wide');echo '</article>';}echo '</div>';if(!$r)emptyState('Eligible dine-in meals appear here after checkout.');
}
